"""
Adiciona a segunda instituição parceira: Associação Renal de Mar de Espanha e
Adjacências (CNPJ 36.392.418/0001-39).

A logo vai embutida como data-URI (mesmo formato que o admin grava em
`Instituicao.logo`) pra instituição nascer completa — sem passo manual de upload
depois do deploy, que é justamente o que ficou pendente na 0003.
"""
from django.db import migrations
from django.db.models.deletion import ProtectedError

_NOME = "Associação Renal de Mar de Espanha e Adjacências"
_ORDEM = 2

# JPEG 720x727 (53 KB brutos, ~70 KB em base64) — bem abaixo do LOGO_MAX_BYTES
# de 250 KB, porque a data-URI viaja no payload público do dropdown.
_LOGO = (
    "data:image/jpeg;base64,"
)


def adicionar_instituicao(apps, schema_editor):
    Instituicao = apps.get_model("instituicoes", "Instituicao")
    instituicao, criada = Instituicao.objects.get_or_create(
        nome=_NOME,
        defaults={"ordem": _ORDEM, "ativo": True, "logo": _LOGO},
    )
    # Se alguém já tinha cadastrado a instituição pelo admin sem logo, completa
    # o registro em vez de deixar o fallback aparecendo em produção.
    if not criada and not instituicao.logo:
        instituicao.logo = _LOGO
        instituicao.save(update_fields=["logo"])


def remover_instituicao(apps, schema_editor):
    Instituicao = apps.get_model("instituicoes", "Instituicao")
    # Repasse aponta pra Instituicao com PROTECT: se já houver ledger, apagar
    # levaria a migração ao chão e apagaria histórico financeiro. Desativa.
    for instituicao in Instituicao.objects.filter(nome=_NOME):
        try:
            instituicao.delete()
        except ProtectedError:
            instituicao.ativo = False
            instituicao.save(update_fields=["ativo"])


class Migration(migrations.Migration):
    dependencies = [
        ("instituicoes", "0004_repasse_quitacao"),
    ]

    operations = [
        migrations.RunPython(adicionar_instituicao, remover_instituicao),
    ]
